CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, login_id TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'USER', created_at TEXT, updated_at TEXT);
CREATE TABLE common_codes (id INTEGER PRIMARY KEY AUTOINCREMENT, code_kind TEXT NOT NULL, code_key TEXT NOT NULL, code_name TEXT NOT NULL, is_admin INTEGER DEFAULT 0, UNIQUE(code_kind, code_key));
CREATE TABLE menus (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER, name TEXT NOT NULL, type TEXT NOT NULL, url TEXT, new_window INTEGER DEFAULT 0, sort INTEGER DEFAULT 0, use_yn INTEGER DEFAULT 1, deleted INTEGER DEFAULT 0, created_at TEXT, updated_at TEXT);
CREATE TABLE menu_permissions (id INTEGER PRIMARY KEY AUTOINCREMENT, menu_id INTEGER NOT NULL, access_level TEXT NOT NULL, UNIQUE(menu_id, access_level));
CREATE TABLE menu_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, menu_id INTEGER NOT NULL, menu_name TEXT, session_id TEXT, user_id INTEGER, access_time TEXT NOT NULL);
CREATE INDEX idx_menu_logs_menu ON menu_logs(menu_id); CREATE INDEX idx_menu_logs_time ON menu_logs(access_time);
CREATE TABLE boards (id INTEGER PRIMARY KEY AUTOINCREMENT, menu_id INTEGER NOT NULL, writer INTEGER NOT NULL, parent_id INTEGER, group_id INTEGER DEFAULT 0, path TEXT DEFAULT '', depth INTEGER DEFAULT 0, title TEXT NOT NULL, content TEXT NOT NULL, is_notice INTEGER DEFAULT 0, notice_start TEXT, notice_end TEXT, view_count INTEGER DEFAULT 0, deleted INTEGER DEFAULT 0, created_at TEXT, updated_at TEXT);
CREATE INDEX idx_boards_menu ON boards(menu_id); CREATE INDEX idx_boards_group ON boards(group_id);
CREATE TABLE comments (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL, parent_id INTEGER, writer INTEGER NOT NULL, content TEXT NOT NULL, deleted INTEGER DEFAULT 0, created_at TEXT, updated_at TEXT);
CREATE INDEX idx_comments_board ON comments(board_id);
CREATE TABLE board_views (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL, user_id INTEGER, viewed_at TEXT NOT NULL);
CREATE INDEX idx_bv_board ON board_views(board_id); CREATE INDEX idx_bv_time ON board_views(viewed_at);
CREATE TABLE board_likes (user_id INTEGER NOT NULL, board_id INTEGER NOT NULL, created_at TEXT, PRIMARY KEY(user_id, board_id));
CREATE TABLE attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL, origin_name TEXT NOT NULL, stored_name TEXT NOT NULL, file_size INTEGER, file_type TEXT, is_thumbnail INTEGER DEFAULT 0, deleted INTEGER DEFAULT 0, created_at TEXT, updated_at TEXT);
CREATE INDEX idx_att_board ON attachments(board_id); CREATE UNIQUE INDEX idx_att_stored ON attachments(stored_name);
CREATE TABLE download_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, attachment_id INTEGER NOT NULL, user_id INTEGER, downloaded_at TEXT);
CREATE INDEX idx_dl_att ON download_logs(attachment_id);
CREATE TABLE hashtags (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL, title TEXT NOT NULL);
CREATE INDEX idx_tag_board ON hashtags(board_id); CREATE INDEX idx_tag_title ON hashtags(title);
CREATE TABLE surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, start_dt TEXT NOT NULL, end_dt TEXT NOT NULL, login_required INTEGER DEFAULT 1, allow_duplicate INTEGER DEFAULT 0, per_page INTEGER DEFAULT 5, use_yn INTEGER DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE question_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, use_yn INTEGER DEFAULT 1);
CREATE TABLE questions (id INTEGER PRIMARY KEY AUTOINCREMENT, survey_id INTEGER NOT NULL, parent_id INTEGER, category_id INTEGER, type TEXT NOT NULL, text TEXT NOT NULL, required INTEGER DEFAULT 1, sort INTEGER DEFAULT 0, max_count INTEGER DEFAULT 1, use_yn INTEGER DEFAULT 1);
CREATE INDEX idx_q_survey ON questions(survey_id);
CREATE TABLE question_options (id INTEGER PRIMARY KEY AUTOINCREMENT, question_id INTEGER NOT NULL, text TEXT NOT NULL, sort INTEGER DEFAULT 0, is_etc INTEGER DEFAULT 0, is_none INTEGER DEFAULT 0);
CREATE INDEX idx_qo_q ON question_options(question_id);
CREATE TABLE survey_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, survey_id INTEGER NOT NULL, user_id INTEGER, submit_count INTEGER DEFAULT 0, status TEXT DEFAULT 'IN_PROGRESS', last_page INTEGER DEFAULT 1, submitted_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE survey_answers (id INTEGER PRIMARY KEY AUTOINCREMENT, log_id INTEGER NOT NULL, question_id INTEGER NOT NULL, option_id INTEGER, answer_text TEXT);
CREATE INDEX idx_sa_log ON survey_answers(log_id); CREATE INDEX idx_sa_q ON survey_answers(question_id);
